import { TemplateTranslation } from './template-translation';
import { SUPPORTED_LANGUAGE_CODES } from '@/shared/config/languages/languages.config';

// Files are generated by `npm run translate:templates`; English is the source and has none.
export const getTemplateTranslation = (
  code: string | null | undefined,
): TemplateTranslation | undefined => {
  if (!code || code === 'en' || !SUPPORTED_LANGUAGE_CODES.includes(code))
    return undefined;
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    return require(`./${code}`).default as TemplateTranslation;
  } catch {
    return undefined; // not generated yet: fall back to English
  }
};
